<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='reports';$pageTitle='Assessment Reports';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$sum=['attempts'=>0,'assessed'=>0,'competent'=>0,'nyc'=>0,'moderated'=>0];$rows=[];if($uid<=0){http_response_code(403);exit('Invalid Assessor account.');}if(as_has_table($conn,'assessment_attempts')){$s=$conn->prepare("SELECT COUNT(*) attempts,SUM(assessor_result IS NOT NULL) assessed,SUM(assessor_result='competent') competent,SUM(assessor_result='not_yet_competent') nyc,SUM(moderation_status='approved') moderated FROM assessment_attempts WHERE assessor_id=?");$s->bind_param('i',$uid);$s->execute();$sum=array_merge($sum,$s->get_result()->fetch_assoc()?:[]);$s->close();$s=$conn->prepare("SELECT ao.code,ao.title,COUNT(*) attempts,SUM(aa.assessor_result='competent') competent,SUM(aa.assessor_result='not_yet_competent') nyc,SUM(aa.moderation_status='approved') approved FROM assessment_attempts aa JOIN assessment_outcomes ao ON ao.id=aa.outcome_id WHERE aa.assessor_id=? GROUP BY ao.id,ao.code,ao.title ORDER BY ao.code");$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}$rate=as_percent((int)$sum['competent'],max(1,(int)$sum['assessed']));require __DIR__.'/_layout_start.php';?>
<div class="as-page-header"><div><span class="as-page-header__eyebrow">Assessment Insights</span><h2>Reports</h2><p>Review your assessment workload, results and moderation outcomes.</p></div></div><section class="as-stats as-stats--5"><article class="as-stat"><span class="as-stat__icon as-stat__icon--blue"><i class="fas fa-list-check"></i></span><strong><?= (int)$sum['attempts'] ?></strong><span>Assigned Attempts</span></article><article class="as-stat"><span class="as-stat__icon as-stat__icon--cyan"><i class="fas fa-gavel"></i></span><strong><?= (int)$sum['assessed'] ?></strong><span>Assessed</span></article><article class="as-stat"><span class="as-stat__icon as-stat__icon--green"><i class="fas fa-circle-check"></i></span><strong><?= (int)$sum['competent'] ?></strong><span>Competent</span></article><article class="as-stat"><span class="as-stat__icon as-stat__icon--red"><i class="fas fa-rotate-right"></i></span><strong><?= (int)$sum['nyc'] ?></strong><span>Not Yet Competent</span></article><article class="as-stat"><span class="as-stat__icon as-stat__icon--purple"><i class="fas fa-percent"></i></span><strong><?= $rate ?>%</strong><span>Competency Rate</span></article></section><div class="as-card"><div class="as-card__header"><div><h3>Outcome Performance</h3><p>Assessment results grouped by outcome.</p></div></div><div class="as-table-wrap"><table class="as-table"><thead><tr><th>Outcome</th><th>Attempts</th><th>Competent</th><th>Not Yet Competent</th><th>Moderation Approved</th><th>Competency</th></tr></thead><tbody><?php foreach($rows as $x):$r=as_percent((int)$x['competent'],max(1,(int)$x['competent']+(int)$x['nyc']));?><tr><td><strong><?= e($x['code']) ?></strong><span class="as-table-sub"><?= e($x['title']) ?></span></td><td><?= (int)$x['attempts'] ?></td><td><?= (int)$x['competent'] ?></td><td><?= (int)$x['nyc'] ?></td><td><?= (int)$x['approved'] ?></td><td><div class="as-progress as-progress--table"><div class="as-progress__labels"><span>Rate</span><strong><?= $r ?>%</strong></div><div class="as-progress__track"><span style="width:<?= $r ?>%"></span></div></div></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/_layout_end.php';?>
